searchDatas1[40] = ['','Herramienta de selección de escáner','./tb_select.html', '	Herramienta de selección de escáner	En esta sección se describen los mensajes de error que pueden aparecer mientas utiliza la Herramienta de selección de escáner y se explican las soluciones de los errores. 	No se pudo modificar el archivo de configuración.	No se pudo procesar a causa de un error inesperado.	Dirección IP no válida. Introduzca una dirección IP correcta.	Error al cargar el archivo de configuración.	No se pudo iniciar el programa.	No se han encontrado archivos de ayuda.	El nombre es incorrecto.Introduzca el nombre correcto.	'];
searchDatas1[41] = ['','No se pudo modificar el archivo de configuración.','./tb_select_01.html', '	No se pudo modificar el archivo de configuración.	Causa 	El problema puede estar causado por los siguientes motivos:	No es posible la creación de un archivo de configuración o la escritura en el archivo de configuración	Error al obtener la ruta del archivo de configuración	Otra aplicación está intentando acceder al archivo de configuración	Solución 	Salga de todas las aplicaciones que se estén ejecutando y reinicie la Herramienta de selección de escáner.'];
searchDatas1[42] = ['','No se pudo procesar a causa de un error inesperado.','./tb_select_03.html', '	No se pudo procesar a causa de un error inesperado.	Causa 	Ha ocurrido un error inesperado.	Solución 	Reinicie el ordenador y después reinicie la Herramienta de selección de escáner.'];
searchDatas1[43] = ['','Dirección IP no válida. Introduzca una dirección IP correcta.','./tb_select_04.html', '	Dirección IP no válida. Introduzca una dirección IP correcta.	Causa 	La dirección IP que ha introducido es incorrecta.	Solución 	Para fi-8040 o fi-7300NX	Compruebe la dirección IP en la pantalla táctil del escáner e introduzca la dirección IP correcta.	Para obtener más información, consulte la Guía del usuario del escáner.	Para fi-8950, fi-8930, fi-8820, fi-8190, fi-8290, fi-8170, fi-8270, fi-8150 o fi-8250	Utilice la Herramienta de configuración de dirección IP para comprobar la dirección IP del escáner e introduzca la dirección IP correcta.	Para obtener detalles sobre cómo iniciar la Herramienta de configuración de dirección IP, consulte 	Iniciar la Herramienta de configuración de dirección IP.'];
searchDatas1[44] = ['','Error al cargar el archivo de configuración.','./tb_select_05.html', '	Error al cargar el archivo de configuración.	Causa 	El problema puede estar causado por los siguientes motivos:	No tiene privilegios de acceso al archivo de configuración	Error al obtener la ruta del archivo de configuración	Otra aplicación está intentando acceder al archivo de configuración	Solución 	Salga de todas las aplicaciones que se estén ejecutando y reinicie la Herramienta de selección de escáner.'];
searchDatas1[45] = ['','No se pudo iniciar el programa.','./tb_select_06.html', '	No se pudo iniciar el programa.	Causa 	El problema puede estar causado por los siguientes motivos:	Se ha producido un error en el ordenador	No hay archivo ejecutable para la Herramienta de configuración de dirección IP	Solución 	Realice las siguientes acciones:	Reinicie el ordenador.	Desinstale Network Setup Tool for fi Series y vuelva a instalarla de nuevo.	Para obtener más información, consulte la Guía del usuario del escáner.'];
searchDatas1[46] = ['','No se han encontrado archivos de ayuda.','./tb_select_07.html', '	No se han encontrado archivos de ayuda.	Causa 	El archivo de ayuda no existe.	Solución 	Desinstale Network Setup Tool for fi Series y vuelva a instalarla de nuevo.	Para obtener más información, consulte la Guía del usuario del escáner.'];
searchDatas1[47] = ['','El nombre es incorrecto.Introduzca el nombre correcto.','./tb_select_08.html', '	El nombre es incorrecto.Introduzca el nombre correcto.	Causa 	El nombre del escáner es incorrecto.	Solución 	Introduzca el nombre correcto.	Los siguientes caracteres están disponibles:	Caracteres alfanuméricos	- (guion)	. (Periodo)	Se puede introducir un máximo de 255 caracteres.'];
searchDatas1[48] = ['','Herramienta de configuración de dirección IP','./tb_ip.html', '	Herramienta de configuración de dirección IP	En esta sección se describen los mensajes de error que pueden aparecer mientas utiliza la Herramienta de configuración de dirección IP y se explican las soluciones de los errores. 	Conecte el escáner al ordenador mediante el cable USB.	Conecte un solo escáner.	Se ha producido un error de comunicación.	El nombre del escáner contiene caracteres no admitidos.	No se puede especificar una dirección reservada para la dirección IP.	No se puede especificar una dirección reservada para la máscara de subred.	La dirección IP o la máscara de subred no son válidas.	La dirección IP tiene un formato incorrecto.	La longitud del prefijo de subred tiene un formato incorrecto.	No se puede especificar una dirección reservada para la puerta de enlace predeterminada.	La puerta de enlace predeterminada tiene un formato incorrecto.	La máscara de subred o la puerta de enlace predeterminada no son válidas.	No se ha introducido un nombre de escáner.	Otro usuario o aplicación está utilizando el escáner.	No se pudo iniciar el programa.	Fallo al iniciar sesión.	No se han encontrado archivos de ayuda.	'];
searchDatas1[49] = ['','Conecte el escáner al ordenador mediante el cable USB.','./tb_ip_01.html', '	Conecte el escáner al ordenador mediante el cable USB.	Causa 	El problema puede estar causado por los siguientes motivos:	El escáner no está conectado al ordenador mediante el cable USB	No se ha instalado el controlador del escáner	El escáner no está encendido	El escáner que está conectado al ordenador no es compatible con la Herramienta de configuración de dirección IP	Solución 	Haga lo que se indica a continuación:	Conecte el escáner al ordenador con el cable USB suministrado con el escáner.	Instale el controlador del escáner.	Para obtener más información, consulte la Guía del usuario del escáner.	Encienda el escáner.	Compruebe qué modelos de escáner son compatibles con la Herramienta de configuración de dirección IP.	Para obtener información detallada, consulte 	Modelos de escáner admitidos.'];
searchDatas1[50] = ['','Conecte un solo escáner.','./tb_ip_02.html', '	Conecte un solo escáner.	Causa 	Hay varios escáneres conectados al ordenador.	Solución 	Cuando conecte el escáner al ordenador mediante el cable USB, conecte un solo escáner.'];
searchDatas1[51] = ['','Se ha producido un error de comunicación.','./tb_ip_03.html', '	Se ha producido un error de comunicación.	Causa 	El problema puede estar causado por los siguientes motivos:	Ha ocurrido un error durante la comunicación con el escáner	Se ha realizado una operación cuando el escáner estaba en pleno proceso de inicialización	La función de red del escáner está deshabilitada 	Solución 	Haga lo que se indica a continuación:	Apague el escáner y luego vuelva a encenderlo.	Compruebe que la inicialización del escáner se ha completado.	Para obtener más información, consulte la Guía del usuario del escáner.	Inicie Software Operation Panel para habilitar la función de red.	Para obtener más información, consulte la Guía del usuario del escáner.'];
searchDatas1[52] = ['','El nombre del escáner contiene caracteres no admitidos.','./tb_ip_04.html', '	El nombre del escáner contiene caracteres no admitidos.	Causa 	Se han establecido caracteres que no se pueden utilizar para el nombre de escáner.	Solución 	Compruebe qué caracteres se han establecido para el nombre de escáner.	Los caracteres disponibles son caracteres alfanuméricos, "-" (guion), "_" (guion bajo) y espacios.'];
searchDatas1[53] = ['','No se puede especificar una dirección reservada para la dirección IP.','./tb_ip_05.html', '	No se puede especificar una dirección reservada para la dirección IP.	Causa 	Se ha configurado una dirección IP no válida.	Solución 	Introduzca una dirección IP correcta.	Para una dirección IPv4	Cada xxx en xxx.xxx.xxx.xxx debe tener un valor entre 0 y 255.	Compruebe lo siguiente e inténtelo de nuevo.	Los valores introducidos son los mismos que los asignados al escáner	Para una dirección IPv6	Cada xxxx en xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx debe ser un valor entre 0 y ffff.	Compruebe lo siguiente e inténtelo de nuevo.	Los valores introducidos son los mismos que los asignados al escáner'];
searchDatas1[54] = ['','No se puede especificar una dirección reservada para la máscara de subred.','./tb_ip_06.html', '	No se puede especificar una dirección reservada para la máscara de subred.	Causa 	Se ha configurado una máscara de subred no válida.	Solución 	Introduzca una máscara de subred válida.	Cada xxx en xxx.xxx.xxx.xxx debe tener un valor entre 0 y 255.	Compruebe lo siguiente e inténtelo de nuevo.	Los valores introducidos son los mismos que los asignados a la máscara de subred'];
searchDatas1[55] = ['','La dirección IP o la máscara de subred no son válidas.','./tb_ip_07.html', '	La dirección IP o la máscara de subred no son válidas.	Causa 	Se ha configurado una dirección IP o una máscara de subred no válida.	Solución 	Introduzca una dirección IP o una máscara de subred válida.	Cada xxx en xxx.xxx.xxx.xxx debe tener un valor entre 0 y 255.	Compruebe que los valores introducidos son los mismos que los asignados al escáner o la máscara de subred, e inténtelo de nuevo.'];
searchDatas1[56] = ['','La dirección IP tiene un formato incorrecto.','./tb_ip_18.html', '	La dirección IP tiene un formato incorrecto.	Causa 	La dirección IP para IPv6 tiene un formato incorrecto.	Solución 	Introduzca la dirección IP en el formato correcto.	Cada xxxx en xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx debe ser un valor entre 0 y ffff.	Compruebe lo siguiente e inténtelo de nuevo.	En los campos de entrada se introduce un valor en número hexadecimal	La forma abreviada (::) se utiliza menos de dos veces	No hay espacios en blanco en los campos de entrada'];
searchDatas1[57] = ['','La longitud del prefijo de subred tiene un formato incorrecto.','./tb_ip_16.html', '	La longitud del prefijo de subred tiene un formato incorrecto.	Causa 	La longitud del prefijo de subred para la dirección IPv6 tiene un formato incorrecto.	Solución 	Introduzca la longitud del prefijo de subred en el formato correcto.	Se puede introducir un valor entre 3 y 128.'];
searchDatas1[58] = ['','No se puede especificar una dirección reservada para la puerta de enlace predeterminada.','./tb_ip_09.html', '	No se puede especificar una dirección reservada para la puerta de enlace predeterminada.	Causa 	Se ha configurado una puerta de enlace predeterminada no válida.	Solución 	Introduzca una puerta de enlace predeterminada.	Para una dirección IPv4	Cada xxx en xxx.xxx.xxx.xxx debe tener un valor entre 0 y 255.	Compruebe lo siguiente e inténtelo de nuevo.	Los valores introducidos son los mismos que los asignados a la puerta de enlace predeterminada	Para una dirección IPv6	Cada xxxx en xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx debe ser un valor entre 0 y ffff.	Compruebe lo siguiente e inténtelo de nuevo.	Los valores introducidos son los mismos que los asignados a la puerta de enlace predeterminada'];
searchDatas1[59] = ['','La puerta de enlace predeterminada tiene un formato incorrecto.','./tb_ip_19.html', '	La puerta de enlace predeterminada tiene un formato incorrecto.	Causa 	La puerta de enlace predeterminada para IPv6 tiene un formato incorrecto.	Solución 	Introduzca la puerta de enlace predeterminada en el formato correcto.	Cada xxxx en xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:xxxx debe ser un valor entre 0 y ffff.	Compruebe lo siguiente e inténtelo de nuevo.	En los campos de entrada se introduce un valor en número hexadecimal	La forma abreviada (::) se utiliza menos de dos veces'];
searchDatas1[60] = ['','La máscara de subred o la puerta de enlace predeterminada no son válidas.','./tb_ip_10.html', '	La máscara de subred o la puerta de enlace predeterminada no son válidas.	Causa 	Se ha configurado una puerta de enlace predeterminada o una máscara de subred no válida.	Solución 	Introduzca una puerta de enlace predeterminada o una máscara de subred válida.	Cada xxx en xxx.xxx.xxx.xxx debe tener un valor entre 0 y 255.	Compruebe que los valores introducidos son los mismos que los asignados a la puerta de enlace predeterminada o la máscara de subred, e inténtelo de nuevo.'];
searchDatas1[61] = ['','No se ha introducido un nombre de escáner.','./tb_ip_14.html', '	No se ha introducido un nombre de escáner.	Causa 	No se ha introducido un nombre de escáner.	Solución 	Introduzca uno o más caracteres en el campo de entrada [Nombre del escáner].	Los caracteres disponibles son caracteres alfanuméricos, "-" (guion), "_" (guion bajo) y espacios.'];
searchDatas1[62] = ['','Otro usuario o aplicación está utilizando el escáner.','./tb_ip_12.html', '	Otro usuario o aplicación está utilizando el escáner.	Causa 	Otra aplicación u otro usuario están utilizando el escáner.	Solución 	Asegúrese de que el escáner no lo esté utilizando otra aplicación u otro usuario.	También salga de la aplicación que está usando el escáner.	Si el problema continúa, apague el escáner y enciéndalo de nuevo.'];
searchDatas1[63] = ['','No se pudo iniciar el programa.','./tb_ip_13.html', '	No se pudo iniciar el programa.	Causa 	El problema puede estar causado por los siguientes motivos:	Se ha producido un error en el ordenador	No hay archivo ejecutable para la Herramienta de selección de escáner	Solución 	Realice las siguientes acciones:	Reinicie el ordenador.	Desinstale Network Setup Tool for fi Series y vuelva a instalarla de nuevo.	Para obtener más información, consulte la Guía del usuario del escáner.'];
searchDatas1[64] = ['','Fallo al iniciar sesión.','./tb_ip_17.html', '	Fallo al iniciar sesión.	Causa 	El problema puede estar causado por los siguientes motivos:	La contraseña que ha especificado es diferente de la contraseña del administrador del escáner	Se ha producido un error en el escáner	Solución 	Realice las siguientes acciones:	Escriba la contraseña del administrador correcta del escáner.	Apague el escáner y luego vuelva a encenderlo.'];
searchDatas1[65] = ['','No se han encontrado archivos de ayuda.','./tb_ip_15.html', '	No se han encontrado archivos de ayuda.	Causa 	El archivo de ayuda no existe.	Solución 	Desinstale Network Setup Tool for fi Series y vuelva a instalarla de nuevo.	Para obtener más información, consulte la Guía del usuario del escáner.'];
searchDatas1[66] = ['','Herramienta de registro del certificado','./tb_cer.html', '	Herramienta de registro del certificado	En esta sección se describen los mensajes de error que pueden aparecer mientras usa la Herramienta de registro del certificado y se explican las soluciones de los errores. 	No se pudo conectar al escáner.	No se pudo obtener información del certificado.	No se pudo eliminar el certificado.	No se pudo registrar el certificado.	Contraseña incorrecta.	'];
searchDatas1[67] = ['','No se pudo conectar al escáner.','./tb_cer_01.html', '	No se pudo conectar al escáner.	Causa 	El problema puede estar causado por los siguientes motivos:	El escáner no está encendido	El escáner no está conectado al ordenador mediante el cable USB	El escáner se encuentra en pleno proceso de inicio	Se está cambiando la configuración del escáner	Hay varios escáneres conectados al ordenador	Otra aplicación está usando el escáner	El escáner que está conectado al ordenador no es compatible con la Herramienta de registro del certificado	Solución 	Realice las siguientes acciones:	Encienda el escáner.	Conecte el escáner al ordenador con el cable USB suministrado con el escáner.	Compruebe que el escáner no se encuentra en pleno proceso de inicio.	Termine de cambiar la configuración del escáner.	Conecte un solo escáner al ordenador.	Salga de otra aplicación que esté utilizando el escáner.	Compruebe qué modelos de escáner son compatibles con la Herramienta de registro del certificado.	Para obtener información detallada, consulte 	Modelos de escáner admitidos.	Si se sigue mostrando el mensaje a pesar de tomar las medidas anteriores, haga lo siguiente:	Apague el escáner y enciéndalo otra vez.	CONSEJO	Cuando intenta apagar el escáner, es posible que se siga mostrando el mensaje "En funcionamiento..." en la pantalla táctil del escáner. Aunque esto ocurra, no debería haber problema en apagar el escáner.	Reinicie el ordenador.	Reinicie la Herramienta de registro del certificado.'];
searchDatas1[68] = ['','No se pudo obtener información del certificado.','./tb_cer_02.html', '	No se pudo obtener información del certificado.	Causa 	Realice las siguientes acciones después de hacer clic en el botón [Establecer] en la 	Ventana [Herramienta de registro del certificado].	Apagado del escáner	Conexión y desconexión del escáner del ordenador mediante el cable USB	Solución 	Realice las siguientes acciones:	Encienda el escáner.	Conecte el escáner al ordenador con el cable USB suministrado con el escáner.	Reinicie la Herramienta de registro del certificado.	Si se sigue mostrando el mensaje a pesar de tomar las medidas anteriores, haga lo siguiente:	Apague el escáner y enciéndalo otra vez.	CONSEJO	Cuando intenta apagar el escáner, es posible que se siga mostrando el mensaje "En funcionamiento..." en la pantalla táctil del escáner. Aunque esto ocurra, no debería haber problema en apagar el escáner.	Reinicie el ordenador.	Reinicie la Herramienta de registro del certificado.'];
searchDatas1[69] = ['','No se pudo eliminar el certificado.','./tb_cer_04.html', '	No se pudo eliminar el certificado.	Causa 	Realice las siguientes acciones después de hacer clic en el botón [Establecer] en la 	Ventana [Herramienta de registro del certificado].	Apagado del escáner	Conexión y desconexión del escáner del ordenador mediante el cable USB	Solución 	Realice las siguientes acciones:	Encienda el escáner.	Conecte el escáner al ordenador con el cable USB suministrado con el escáner.	Reinicie la Herramienta de registro del certificado.	Si se sigue mostrando el mensaje a pesar de tomar las medidas anteriores, haga lo siguiente:	Apague el escáner y enciéndalo otra vez.	CONSEJO	Cuando intenta apagar el escáner, es posible que se siga mostrando el mensaje "En funcionamiento..." en la pantalla táctil del escáner. Aunque esto ocurra, no debería haber problema en apagar el escáner.	Reinicie el ordenador.	Reinicie la Herramienta de registro del certificado.'];
searchDatas1[70] = ['','No se pudo registrar el certificado.','./tb_cer_05.html', '	No se pudo registrar el certificado.	Causa 	El problema puede estar causado por los siguientes motivos:	El formato del certificado especificado no es correcto	Error al cargar el certificado especificado	Realice las siguientes acciones después de hacer clic en el botón [Establecer] en la 	Ventana [Herramienta de registro del certificado]	Apagado del escáner	Conexión y desconexión del escáner del ordenador mediante el cable USB	Solución 	Realice las siguientes acciones:	Compruebe que el formato del certificado es correcto.	Los certificados que se pueden registrar son los siguientes:	Certificados del cliente: Formato de archivo PKCS#12 (*.p12, *.pfx)	Certificados de CA: Archivo de certificado de CA (*.cer, *.crt, *.der, *.pem)	Compruebe que tiene privilegios de acceso al archivo de certificado.	Encienda el escáner.	Conecte el escáner al ordenador con el cable USB suministrado con el escáner.	Reinicie la Herramienta de registro del certificado.	Si se sigue mostrando el mensaje a pesar de tomar las medidas anteriores, haga lo siguiente:	Apague el escáner y enciéndalo otra vez.	CONSEJO	Cuando intenta apagar el escáner, es posible que se siga mostrando el mensaje "En funcionamiento..." en la pantalla táctil del escáner. Aunque esto ocurra, no debería haber problema en apagar el escáner.	Reinicie el ordenador.	Reinicie la Herramienta de registro del certificado.'];
searchDatas1[71] = ['','Contraseña incorrecta.','./tb_cer_06.html', '	Contraseña incorrecta.	Causa 	La contraseña que especificó es incorrecta.	Solución 	Introduzca la contraseña correcta.	Pueden usarse los siguientes caracteres para la contraseña.	Caracteres alfanuméricos	A-Z, a-z, 0-9	Símbolos	! " # $ % & \' ( ) * + , - . / : ; < = > ? @ [ 	\\ ] ^ _ ` { | } ~	Espacios'];
searchDatas1[72] = ['','Button Event Manager','./tb_bem.html', '	Button Event Manager	En esta sección se describen los mensajes de error que pueden aparecer mientras utiliza Button Event Manager y se explican las soluciones de los errores. 	No se pudo procesar a causa de un error inesperado.	No se han encontrado archivos de ayuda.	'];
searchDatas1[73] = ['','No se pudo procesar a causa de un error inesperado.','./tb_bem_01.html', '	No se pudo procesar a causa de un error inesperado.	Causa 	Ha ocurrido un error inesperado.	Solución 	Reinicie el ordenador y reinicie Button Event Manager.'];
searchDatas1[74] = ['','No se han encontrado archivos de ayuda.','./tb_bem_02.html', '	No se han encontrado archivos de ayuda.	Causa 	El archivo de ayuda no existe.	Solución 	Desinstale Network Setup Tool for fi Series y vuelva a instalarla de nuevo.	Para obtener más información, consulte la Guía del usuario del escáner.'];
searchDatas1[75] = ['','Solución de problemas','./title_trouble.html', '	Solución de problemas	En esta sección se describen los problemas que pueden producirse mientas usa Network Setup Tool for fi Series y se explican las soluciones de los problemas. 	No se han encontrado escáneres	No se puede realizar una digitalización pulsando el botón del escáner	'];
searchDatas1[76] = ['','No se han encontrado escáneres','./trouble_01.html', '	No se han encontrado escáneres	Compruebe lo siguiente: 	¿El método de conexión (usado para conectarse al escáner) es diferente del que está configurado en los ajustes del escáner? (fi-7300NX)	¿Están configurados correctamente los ajustes de red del escáner?	¿El escáner se encuentra en pleno proceso de inicio o inicialización?	¿Hay otra aplicación que esté utilizando el escáner?	¿Están configurados correctamente los ajustes de red del ordenador?	¿Se está actualizando el sistema operativo del ordenador o está esperando para reiniciarse?	¿Están el escáner y el ordenador conectados a la misma subred?	¿Son correctos los ajustes de los dispositivos de red (como un conmutador, hub o router)?	¿Es estable el estado de la comunicación entre el escáner y el ordenador?	Si no se encuentran escáneres después de tomar las medidas anteriores, reinicie el escáner y el ordenador y después reinicie la Herramienta de selección de escáner.	Si un escáner no aparece en la aplicación de digitalización de imágenes, consulte 	No se puede realizar una digitalización desde la aplicación de digitalización de imágenes.	¿El método de conexión (usado para conectarse al escáner) es diferente del que está configurado en los ajustes del escáner? (fi-7300NX)	Solución 	Compruebe que ha configurado Wi-Fi o una LAN con cable como método de conexión del escáner.	Puede comprobarlo siguiendo los pasos descritos a continuación.	En la pantalla táctil del escáner, pulse 	 	→ [Ajustes del escáner] 	→ [Método de conexión].	¿Están configurados correctamente los ajustes de red del escáner?	Solución 	Para fi-8040 o fi-7300NX	Compruebe la configuración de red del escáner.	Puede comprobarlo siguiendo los pasos descritos a continuación.	En la pantalla táctil del escáner, pulse 	 	→ [Ajustes del escáner] 	→ [Red].	Para fi-8950, fi-8930, fi-8820, fi-8190, fi-8290, fi-8170, fi-8270, fi-8150 o fi-8250	Utilice la Herramienta de configuración de dirección IP para comprobar la configuración de red del escáner.	Para obtener detalles sobre cómo iniciar la Herramienta de configuración de dirección IP, consulte 	Iniciar la Herramienta de configuración de dirección IP.	¿El escáner se encuentra en pleno proceso de inicio o inicialización?	Solución 	Compruebe que el escáner no se encuentra en pleno proceso de inicio o inicialización.	Para obtener más información, consulte la Guía del usuario del escáner.	¿Hay otra aplicación que esté utilizando el escáner?	Solución 	Salga de otra aplicación que esté utilizando el escáner.	¿Están configurados correctamente los ajustes de red del ordenador?	Solución 	Compruebe los ajustes de red del ordenador.	Para obtener más detalles sobre cómo configurar los ajustes de red del ordenador, consulte el manual del ordenador.	¿Se está actualizando el sistema operativo del ordenador o está esperando para reiniciarse?	Solución 	Reinicie la Herramienta de selección de escáner después de haber actualizado el sistema operativo o de haber reiniciado el ordenador.	¿Están el escáner y el ordenador conectados a la misma subred?	Es posible que no se detecte el escáner aunque esté conectado a la misma subred que el ordenador.	Solución 	Seleccione [Buscar desde la dirección IP del escáner] en la 	Ventana [Herramienta de selección de escáner] e introduzca la dirección IP para buscar el escáner.	¿Son correctos los ajustes de los dispositivos de red (como un conmutador, hub o router)?	Solución 	Compruebe los ajustes de los dispositivos de red (como un conmutador, hub o router).	Para obtener información acerca de la configuración del dispositivo de red, consulte el manual del dispositivo de red.	¿Es estable el estado de la comunicación entre el escáner y el ordenador?	Solución 	Para fi-8040 o fi-7300NX	Compruebe el estado de la comunicación entre el escáner y el ordenador.	Puede comprobar el estado de comunicación entre el escáner y el ordenador en la pantalla táctil del escáner.	Puede comprobarlo siguiendo los pasos descritos a continuación.	En la pantalla táctil del escáner, pulse 	 	→ [Ajustes del escáner] 	→ [Red] 	→ [Comprobar conexión (Ping)].	Para fi-8950, fi-8930, fi-8820, fi-8190, fi-8290, fi-8170, fi-8270, fi-8150 o fi-8250	Compruebe el estado de la comunicación entre el escáner y el ordenador.	Inicie el símbolo del sistema del ordenador y ejecute el comando ping para comprobar el estado de comunicación especificando la dirección IP del escáner.	Utilice la Herramienta de configuración de dirección IP para comprobar la configuración IP del escáner.	Para obtener detalles sobre cómo iniciar la Herramienta de configuración de dirección IP, consulte 	Iniciar la Herramienta de configuración de dirección IP.'];
searchDatas1[77] = ['','No se puede realizar una digitalización pulsando el botón del escáner','./trouble_02.html', '	No se puede realizar una digitalización pulsando el botón del escáner	Compruebe lo siguiente: 	¿Se ha seleccionado el escáner en la Herramienta de selección de escáner?	¿Se ha iniciado Button Event Manager?	¿Se ha seleccionado [Evento Mirar el botón] en el menú de Button Event Manager?	¿Es correcta la configuración del botón en el escáner?	¿El escáner lo está utilizando otro ordenador?	¿Se ha seleccionado el escáner en la Herramienta de selección de escáner?	Solución 	En la 	Ventana [Herramienta de selección de escáner], compruebe que el escáner esté seleccionado.	¿Se ha iniciado Button Event Manager?	Solución 	Compruebe que Button Event Manager se ha iniciado.	Cuando se ha iniciado Button Event Manager, aparece 	 en el área de notificaciones ubicada en el lado derecho de la barra de tareas.	Para obtener detalles sobre cómo iniciar Button Event Manager, consulte 	Iniciar Button Event Manager.	¿Se ha seleccionado [Evento Mirar el botón] en el menú de Button Event Manager?	Solución 	Inicie Button Event Manager y haga clic con el botón derecho en 	 en el área de notificaciones ubicada en el lado derecho de la barra de tareas para que se muestre el 	Menú de Button Event Manager. Compruebe que [Evento Mirar el botón] esté seleccionado.	Para obtener detalles sobre cómo iniciar Button Event Manager, consulte 	Iniciar Button Event Manager.	¿Es correcta la configuración del botón en el escáner?	Solución 	En la 	Ventana [Ajustes del botón] de Button Event Manager, compruebe que el ajuste del botón es el correcto.	Compruebe que la aplicación de digitalización de imágenes que ha especificado para el botón en el escáner se está ejecutando en el ordenador.	¿El escáner lo está utilizando otro ordenador?	Solución 	Cuando el escáner esté seleccionado en más de un ordenador al utilizar la herramienta de selección de escáner, seleccione [Evento Mirar el botón] en el menú de Button Event Manager solo en el ordenador en el que quiera utilizar el escáner.	Si no puede iniciar una digitalización a pesar de tomar las medidas anteriores, haga lo siguiente:	Salga de la aplicación de digitalización de imágenes ubicada en el área de notificaciones ubicada lado derecho de la barra de tareas	Apague el escáner y enciéndalo otra vez'];
searchDatas1[78] = ['','Modelos de escáner admitidos','./support.html', '	Modelos de escáner admitidos	A continuación se detallan los modelos de escáner admitidos por Network Setup Tool for fi Series. 	Herramienta de selección de escáner	fi-8950, fi-8930, fi-8820, fi-8040, fi-8190, fi-8290, fi-8170, fi-8270, fi-8150, fi-8250, fi-7300NX	Herramienta de configuración de dirección IP	fi-8950, fi-8930, fi-8820, fi-8190, fi-8290, fi-8170, fi-8270, fi-8150, fi-8250	Herramienta de registro del certificado	fi-7300NX	Button Event Manager	fi-8950, fi-8930, fi-8820, fi-8040, fi-8190, fi-8290, fi-8170, fi-8270, fi-8150, fi-8250, fi-7300NX'];
searchDatas1[79] = ['','No se puede realizar una digitalización desde la aplicación de digitalización de imágenes','./trouble_04.html', '	No se puede realizar una digitalización desde la aplicación de digitalización de imágenes	Compruebe lo siguiente: 	¿Se ha configurado un servidor proxy para el ajuste de proxy WinHTTP?	¿Se ha configurado un servidor proxy para el ajuste de proxy WinHTTP?	Solución 	Cambie la configuración del proxy WinHTTP para que pueda acceder al escáner desde el ordenador.	Cambie la configuración del proxy WinHTTP mediante el siguiente procedimiento.	Inicie la ventana del símbolo del sistema como usuario con privilegios de administrador en el ordenador.	Ejecute el siguiente comando para comprobar el nombre del servidor proxy y los números de puerto que se van a usar.	netsh winhttp show proxy	CONSEJO	A continuación se mostrará el nombre del servidor proxy y los números de puerto que se van a usar.	"Nombre del servidor proxy: Números de puerto"	Ejecute uno de los siguientes comandos.	Cuando ya se ha configurado un servidor proxy	Configure los ajustes para que el ordenador pueda acceder al escáner sin usar el servidor proxy.	netsh winhttp set proxy proxy-server="XXXXXX:YYYY" bypass-list=ZZZ.ZZZ.ZZZ.ZZZ	XXXXXX: nombre del servidor proxy	YYYY: números de puertos que se usarán	ZZZ.ZZZ.ZZZ.ZZZ: Dirección IP del escáner (*1)(*2)	Cuando no se ha configurado el servidor proxy	Si restablece la configuración, es posible que el ordenador pueda tener acceso al escáner.	netsh winhttp reset proxy	*1:	Puede comprobar la dirección IP del escáner en la pantalla táctil o el panel del operador del escáner o la Herramienta de configuración de dirección IP.	*2:	Aquí se muestra como ejemplo un formato de la dirección IPv4.	Para una dirección Ipv6, se utiliza el siguiente formato.	ZZZZ:ZZZZ:ZZZZ:ZZZZ:ZZZZ:ZZZZ:ZZZZ:ZZZZ'];
searchDatas1[80] = ['','Contraseña de administrador para el escáner','./adminpassword.html', '	Contraseña de administrador para el escáner	Para obtener más información acerca de la contraseña del administrador predeterminada de fábrica, consulte la Guía del usuario del escáner.'];
